class UserNotFound extends Error { readonly kind = "UserNotFound" }

const getUser = (id: string) => {
  const user = db.get(id);
  if (!user) return new UserNotFound(id);
  return user;
};

const r = getUser("1");          // 返回类型: User | UserNotFound
if (r instanceof UserNotFound) { /* 处理 */ } else { r.name }

